	v1Start = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)  // 零价版生效起点（含）
	v1End   = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC) // 零价版结束时刻（不含）
)

